  "stuSess.penaltyChoiceDesc": "Annuleringskosten: €{penalty}. Terug te betalen bedrag: €{refundable}.",
  "stuSess.penaltyChoiceDescEarly": "Je hebt €{refundable} betaald voor deze les. Kies accounttegoed voor je volgende boeking of een terugbetaling.",
