  "stuSess.penaltyChoiceCreditDesc": "€{amount} wordt toegevoegd aan je tegoed en automatisch toegepast op je volgende les.",
  "stuSess.penaltyChoiceRefund": "Terugbetaling naar betaalmethode",
  "stuSess.penaltyChoiceRefundDesc": "Neem voor een terugbetaling (€{amount}) contact op met info@tutlio.lt. Als je met een kaart hebt betaald, kan de terugbetaling mogelijk automatisch via Stripe worden gestart.",
  "stuSess.creditAvailable": "Beschikbaar krediet",
  "stuSess.payWithCredit": "Betaal met krediet",
  "stuSess.creditAppliedSuccess": "€{amount} tegoed is toegevoegd aan je saldo en wordt automatisch toegepast op je volgende les.",
  "stuSess.refundContactNote": "Neem voor een terugbetaling contact op met <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Vragen of problemen? Neem contact op via <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Je terugbetaling via Stripe is gestart.</p><p class=\"text-emerald-800 mt-1\">Terugbetalingen naar een kaart worden meestal binnen <strong>5–10 werkdagen</strong> bijgeschreven, afhankelijk van de bank. Heb je de terugbetaling daarna nog niet ontvangen? Stuur dan een e-mail naar <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Deze les lijkt niet via Stripe op Tutlio te zijn betaald, maar bijvoorbeeld via bankoverschrijving of contant. Er wordt daarom niet automatisch terugbetaald.</p><p class=\"mt-2\">Neem voor een terugbetaling rechtstreeks contact op met je docent <strong>{tutor}</strong>, via het e-mailadres in je boekingsgegevens of via de contactgegevens van de docent.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Het lijkt erop dat deze les niet is betaald via Tutlio Stripe (bijvoorbeeld via bankoverschrijving of contant). Er vindt hier geen automatische terugbetaling plaats.</p><p class=\"mt-2\">Omdat je via een organisatie leert, kun je contact opnemen met de <strong>organisatiebeheerder</strong> (via je docent of de gepubliceerde contactpersonen van de organisatie).</p>",
  "stuSess.refundTutorFallback": "jouw docent",
