  "schoolsLanding.heroSpot2Title": "Wachtlijst",
  "schoolsLanding.heroSpot2Body": "Vervang papieren lijsten door geautomatiseerde wachtlijsten en vul plekken na annuleringen sneller op, met minder administratie en minder omzetverlies.",
  "schoolsLanding.heroMoreFeaturesCta": "Meer functies",
  "schoolsLanding.trustText": "Gebouwd voor scholen die de administratie en het lesmanagement willen digitaliseren.",
