  "schoolsLanding.stepsDesc": "Digitaliseer je schoolactiviteiten door je structuur op te zetten, lessen te lanceren en resultaten bij te houden – allemaal vanaf één platform.",
  "schoolsLanding.step1Title": "Richt je school in",
  "schoolsLanding.step1Desc": "Configureer vakken, groepen, docentenrollen en lesregels op basis van de behoeften van je school. Nodig docenten uit en wijs verantwoordelijkheden toe.",
  "schoolsLanding.step2Title": "Lessen starten en uitvoeren",
  "schoolsLanding.step2Desc": "Nodig leerlingen uit, publiceer roosters en houd activiteiten op één lijn met geautomatiseerde herinneringen en meldingen.",
  "schoolsLanding.step3Title": "Meten & optimaliseren",
  "schoolsLanding.step3Desc": "Gebruik aanwezigheids- en voortgangsinzichten om de programmakwaliteit te verbeteren, KPI's bij te houden en duidelijke rapporten aan je team te leveren.",
  "schoolsLanding.featuresBadge": "Functies",
