  "schoolsLanding.featuresSubtitle": "Van lesplanning tot financiële rapportage — Tutlio Schools geeft je administratie de middelen om efficiënt te werken.",
  "schoolsLanding.feat.scheduling": "Lesplanning",
  "schoolsLanding.feat.schedulingDesc": "Beheer lessen, onderwerpen en werklasten voor docenten in één kalender.",
  "schoolsLanding.feat.schedulingHeading": "Plannen & Organiseren ",
  "schoolsLanding.feat.schedulingHighlight": "Jouw lessen",
  "schoolsLanding.feat.schedulingB1": "Plan eenmalige en terugkerende lessen voor alle docenten in één uniforme kalender.",
  "schoolsLanding.feat.schedulingB2": "Stel automatisch boekingsregels, buffertijden en maximale groepsgroottes in.",
  "schoolsLanding.feat.schedulingB3": "Bekijk het volledige schoolrooster per dag, week of maand – met alle docenten en vakken.",
  "schoolsLanding.feat.waitlist": "Docentenmanagement",
  "schoolsLanding.feat.waitlistDesc": "Wijs docenten toe, beheer de werklast en organiseer leerlingengroepen.",
  "schoolsLanding.feat.waitlistHeading": "Beheer docenten en ",
  "schoolsLanding.feat.waitlistHighlight": "Leerlingengroepen",
  "schoolsLanding.feat.waitlistB1": "Wijs docenten toe aan vakken en leerlingengroepen zonder spreadsheet-overhead.",
  "schoolsLanding.feat.waitlistB2": "Houd de werklast en beschikbaarheid van docenten in de hele school in de gaten.",
  "schoolsLanding.feat.waitlistB3": "Op rollen gebaseerde toegang zorgt ervoor dat docenten alleen hun leerlingen en lessen zien.",
  "schoolsLanding.feat.payments": "Financiën en contracten",
  "schoolsLanding.feat.paymentsDesc": "Betalingsinning, contractbeheer en financiële overzichten.",
  "schoolsLanding.feat.paymentsHeading": "Stroomlijnen ",
  "schoolsLanding.feat.paymentsHighlight": "Schoolfinanciën",
