  "schoolsLanding.faq.whoForA": "Taalscholen, bijlescentra, muziekscholen, examenvoorbereidingsprogramma's en elke organisatie die meerdere docenten en leerlingen beheert.",
  "schoolsLanding.faq.contractsQ": "Kunnen we contracten en betalingen beheren?",
  "schoolsLanding.faq.contractsA": "Ja. Het platform ondersteunt contractsjablonen, elektronische ondertekening, termijnplannen, Stripe-betalingen en financiële rapportage.",
  "schoolsLanding.faq.pricingQ": "Hoe werkt de schoolprijs?",
