  "orgTutorPolicy.title": "Interne regels voor docenten",
  "orgTutorPolicy.intro": "Lees de interne regels van de organisatie voordat u het platform gebruikt.",
  "orgTutorPolicy.acceptBtn": "Ik begrijp het",
  "orgTutorPolicy.viewBtn": "Bekijk interne regels",
  "orgTutorPolicy.s1Title": "1. Algemene bepalingen",
  "orgTutorPolicy.s1Body": "Deze regels zijn van toepassing op uw gebruik van het Tutlio-platform (het \"Platform\") als leraar of bijlesdocent (de \"Docent\"). U bent uitgenodigd om het Platform te gebruiken door de onderwijsinstelling, school of het bijlescentrum dat u vertegenwoordigt (de \"Organisatie\"). Het Platform wordt technisch onderhouden en ondersteund door MB Tutlio. Door uw account te gebruiken, gaat u akkoord met deze regels en het privacybeleid.",
  "orgTutorPolicy.s2Title": "2. Accountbeheer en planningen",
  "orgTutorPolicy.s2Intro": "Het platform is zo ontworpen dat u geen tijd hoeft te besteden aan het afstemmen van de lestijden met leerlingen.",
  "orgTutorPolicy.s2Link": "Unieke link: Je krijgt een persoonlijke lesboekingslink toegewezen (gebaseerd op de vakken die je geeft) die leerlingen gebruiken om lessen in te plannen.",
  "orgTutorPolicy.s2Calendar": "Agendasynchronisatie: uw beschikbaarheid is rechtstreeks afhankelijk van uw Google Calendar-integratie (synchronisatie in twee richtingen). U bent er persoonlijk verantwoordelijk voor dat de beschikbaarheid die in uw agenda wordt weergegeven juist en actueel is. Het Platform staat leerlingen niet toe om tijden te reserveren die in uw agenda als druk zijn gemarkeerd.",
  "orgTutorPolicy.s2Security": "Accountbeveiliging: Uw account is persoonlijk. U dient uw inloggegevens veilig te bewaren en deze niet met derden te delen.",
  "orgTutorPolicy.s3Title": "3. Annuleringen van lessen en wachtlijst",
  "orgTutorPolicy.s3Intro": "Het platform helpt u uw planning te maximaliseren en lege plaatsen te vermijden:",
  "orgTutorPolicy.s3Auto": "Als een leerling een les annuleert, stuurt het platform automatisch een melding (SMS/e-mail) naar andere leerlingen op uw wachtlijst, waarin het vrijgekomen tijdslot wordt aangeboden. Er is geen aanvullende actie van u nodig.",
  "orgTutorPolicy.s3Rules": "Regels voor het annuleren van lessen (hoe lang van tevoren een les kan worden geannuleerd, gevolgen) worden bepaald door uw organisatie.",
  "orgTutorPolicy.s4Title": "4. Financiën en betalingen",
  "orgTutorPolicy.s4Intro": "U hoeft zich geen zorgen te maken over het factureren of innen van betalingen bij ouders:",
  "orgTutorPolicy.s4Advance": "Alle leerling- (of ouder-)betalingen voor uw lessen worden vooraf via het Platform geïnd en rechtstreeks naar uw Organisatie overgemaakt.",
  "orgTutorPolicy.s4Confirmed": "Je geeft pas een les als deze in het systeem is bevestigd (dat wil zeggen dat deze al in rekening is gebracht).",
  "orgTutorPolicy.s4Contact": "Voor uw salaris, uitbetalingsschema en andere financiële zaken kunt u rechtstreeks contact opnemen met de beheerder van uw organisatie. MB Tutlio voert geen directe financiële transacties uit met docenten.",
  "orgTutorPolicy.s5Title": "5. Bescherming van leerlingengegevens (AVG)",
  "orgTutorPolicy.s5Intro": "Als docent heb je toegang tot de persoonlijke gegevens van leerlingen, interne aantekeningen en leermateriaal. Je engageert je om:",
  "orgTutorPolicy.s5Use": "Gebruik deze gegevens uitsluitend voor het organiseren en geven van lessen.",
  "orgTutorPolicy.s5NoCopy": "Het niet kopiëren, exporteren of verspreiden van de contactgegevens van leerlingen of ouders buiten het Platform.",
  "orgTutorPolicy.s5Notes": "Het beveiligen van interne organisatiegegevens (aantekeningen over de studievoortgang) die alleen zichtbaar zijn voor u en de administratie van de organisatie, niet voor leerlingen of ouders.",
  "orgTutorPolicy.s5Termination": "Bij beëindiging van uw werkrelatie met de Organisatie wordt uw toegang tot deze gegevens onmiddellijk ingetrokken.",
  "orgTutorPolicy.s6Title": "6. Technische werking en aansprakelijkheidsbeperking",
  "orgTutorPolicy.s6Body": "Het is verboden het Platform te gebruiken voor onwettige doeleinden, het verspreiden van kwaadaardige links in lesmateriaal of het anderszins verstoren van het systeem. MB Tutlio zorgt voor de werking en het technisch onderhoud van het Platform, maar aanvaardt geen verantwoordelijkheid voor storingen veroorzaakt door uw internetverbinding, apparaatstoringen of onjuist geconfigureerde Google Calendar-instellingen.",
  "orgTutorPolicy.s7Title": "7. Ondersteuning en contacten",
  "orgTutorPolicy.s7Org": "Voor vragen over lesroosters, salarissen, leerlingenopdrachten of werkorganisatie kunt u contact opnemen met de beheerder van uw organisatie.",
  "orgTutorPolicy.s7Tech": "Voor technische platformfouten (agendasynchronisatie werkt niet, geen meldingen ontvangen), informeer dan de beheerder van uw organisatie, die contact zal opnemen met het technische ondersteuningsteam van Tutlio.",
  "register.orgPolicyConsent": "Door ons platform te gebruiken, ga je akkoord met de",
  "register.orgPolicyLink": "intern beleid",
